using namespace rtabmap;
void need(bool v,const char*m){if(!v)throw std::runtime_error(m);}
ParametersMap params(const std::string&path){ParametersMap p;std::ifstream in(path);need(in.good(),"parameter input");std::string l;while(std::getline(in,l)){auto k=l.find('\t');need(k!=std::string::npos,"parameter row");p[l.substr(0,k)]=l.substr(k+1);}p["Grid/RayTracing"]="true";return p;}
cv::Mat points(std::initializer_list<cv::Vec3f> xs){if(xs.size()==0)return cv::Mat();cv::Mat m(1,xs.size(),CV_32FC3);int i=0;for(auto x:xs)m.at<cv::Vec3f>(0,i++)=x;return m;}
double probability(const OctoMap&m,cv::Vec3f p){auto n=m.octree()->search(p[0],p[1],p[2]);need(n!=nullptr,"expected observed cell");return n->getOccupancy();}
bool occupied(const OctoMap&m,cv::Vec3f p){auto n=m.octree()->search(p[0],p[1],p[2]);return n&&m.octree()->isNodeOccupied(n);}
void fixtures(const ParametersMap&p){
 LocalGridCache cache;OctoMap map(&cache,p);std::map<int,Transform> poses;poses[1]=Transform::getIdentity();cv::Vec3f hit(1.01,.01,.01),far(2.01,.01,.01);
 cache.add(1,cv::Mat(),points({hit}),cv::Mat(),.04f);need(map.update(poses),"native hit update");need(occupied(map,hit),"hit occupied");double first=probability(map,hit);need(std::abs(first-.7)<1e-5,"native hit probability0.7");need(map.octree()->search(1.0,1.0,1.0)==nullptr,"unobserved remains unknown");
 poses[2]=Transform::getIdentity();cache.add(2,cv::Mat(),cv::Mat(),cv::Mat(),.04f);map.update(poses);need(std::abs(probability(map,hit)-first)<1e-8,"missing evidence does not clear");need(map.octree()->search(1.0,1.0,1.0)==nullptr,"missing evidence not free");
 double previous=first;for(int id=3;id<=10;++id){cache.add(id,cv::Mat(),points({far}),cv::Mat(),.04f);poses[id]=Transform::getIdentity();need(map.update(poses),"native further observation update");double q=probability(map,hit);need(q<=previous+1e-6,"repeated observed free monotonically lowers old hit");previous=q;}
 need(!occupied(map,hit)&&previous<.5,"repeated native free rays clear old hit");auto cleared=map.octree()->search(hit[0],hit[1],hit[2]);need(cleared->getOccupancyType()==RtabmapColorOcTreeNode::kTypeObstacle&&cleared->getNodeRefId()==1,"cleared cell retains historical obstacle type/refID, probability authoritative");need(!map.update(poses),"same pose prefix not integrated twice");need(std::abs(probability(map,hit)-previous)<1e-8,"duplicate prefix cannot add misses");need(occupied(map,far),"far measured endpoint remains occupied");need(map.octree()->search(1.0,1.0,1.0)==nullptr,"unseen remains unknown after free rays");std::cout<<"FIXTURE hitProbability="<<first<<" afterFree="<<previous<<std::endl;
 LocalGridCache duplicateCache;OctoMap duplicateMap(&duplicateCache,p);duplicateCache.add(1,cv::Mat(),points({hit,cv::Vec3f(1.02,.02,.02)}),cv::Mat(),.04f);duplicateMap.update({{1,Transform::getIdentity()}});need(std::abs(probability(duplicateMap,hit)-(.49/.58))<1e-5,"native duplicate endpoint weighting retained, not normalized");
 LocalGridCache c2;OctoMap m2(&c2,p);cv::Vec3f low(1.01,.01,.05),head(1.01,.01,1.61),ground(1.01,.41,-.21);c2.add(1,points({ground}),points({low,head}),cv::Mat(),.04f);std::map<int,Transform> p2{{1,Transform::getIdentity()}};m2.update(p2);need(occupied(m2,low)&&occupied(m2,head),"separate low and head hazards retained");auto g=m2.octree()->search(ground[0],ground[1],ground[2]);need(g&&g->getOccupancyType()==RtabmapColorOcTreeNode::kTypeGround,"native ground distinct from obstacle/free");
 LocalGridCache c3;OctoMap m3(&c3,p);Transform t(0,-1,0,3,1,0,0,4,0,0,1,5);c3.add(1,cv::Mat(),points({hit}),cv::Mat(),.04f);m3.update({{1,t}});need(occupied(m3,cv::Vec3f(2.99,5.01,5.01)),"nonidentity node transform correct");
 auto A=Transform::rtabmap_T_opengl(),B=Transform::opengl_T_rtabmap(),O=CameraModel::opticalRotation();auto round=(t*O.inverse())*O;for(int r=0;r<3;++r)for(int c=0;c<4;++c)need(std::abs(round(r,c)-t(r,c))<1e-6,"pose basis roundtrip");
 std::cout<<"NATIVE_OCCUPANCY_FIXTURES_PASSED"<<std::endl;
}
int main(int argc,char**argv){try{need(argc==3||argc==6,"usage: parameters --fixtures OR parameters database poses output mode");auto p=params(argv[1]);ULogger::setLevel(ULogger::kWarning);fixtures(p);if(argc==3){need(std::string(argv[2])=="--fixtures","fixture mode");return 0;}
 std::string out=argv[4];need(std::string(argv[5])=="zup-regenerated-grid","explicit fixed grid arm");std::ofstream config(out+"/PARAMETERS.tsv");for(auto&kv:p)config<<kv.first<<'\t'<<kv.second<<'\n';config.close();std::unique_ptr<DBDriver> db(DBDriver::create());need(db->openConnection(argv[2],false,true),"read-only saved DB");
 LocalGridCache cache;OctoMap map(&cache,p);std::map<int,Transform> poses;std::ifstream in(argv[3]);need(in.good(),"poses readable");std::string line;int n=0;auto A=Transform::rtabmap_T_opengl(),B=Transform::opengl_T_rtabmap(),O=CameraModel::opticalRotation();std::ofstream log(out+"/FRAMES.tsv");log<<"id\tground\tobstacles\tempty\toctreeNodes\tmemoryBytes\tseconds\n";
 while(std::getline(in,line)){std::istringstream s(line);int id;float v[12];s>>id;for(float&x:v)s>>x;need(bool(s),"pose row");need(id==++n,"exact ordered IDs1..265");auto start=std::chrono::steady_clock::now();Transform optical(v[0],v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8],v[9],v[10],v[11]);Transform node=optical*O.inverse();auto back=node*O;for(int r=0;r<3;++r)for(int c=0;c<4;++c)need(std::abs(back(r,c)-optical(r,c))<1e-5,"fixed coordinate identity");
 SensorData data;db->getNodeData(id,data,false,false,false,true);data.uncompressData();need(std::abs(data.gridCellSize()-.04)<1e-6,"native grid resolution");auto view=data.gridViewPoint();need(std::abs(view.x)+std::abs(view.y)+std::abs(view.z)<1e-6,"zero stored sensor translation required");need(data.gridEmptyCellsRaw().empty(),"no existing free cells expected");need(!data.gridGroundCellsRaw().empty()||!data.gridObstacleCellsRaw().empty(),"observed endpoints expected");cache.add(id,data.gridGroundCellsRaw(),data.gridObstacleCellsRaw(),data.gridEmptyCellsRaw(),data.gridCellSize(),view);poses[id]=node;need(map.update(poses),"native incremental occupancy update");log<<id<<'\t'<<data.gridGroundCellsRaw().total()<<'\t'<<data.gridObstacleCellsRaw().total()<<'\t'<<data.gridEmptyCellsRaw().total()<<'\t'<<map.octree()->size()<<'\t'<<map.getMemoryUsed()<<'\t'<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<'\n';log.flush();std::cout<<"FRAME "<<id<<" nodes="<<map.octree()->size()<<std::endl;}
 need(n==265,"265 frozen local grids");need(map.octree()->write(out+"/native_probability_tree.ot"),"native probability tree write");
 std::ofstream leaves(out+"/leaves_dataset_world.bin",std::ios::binary);std::ofstream occupiedIndex(out+"/occupied_leaf_indices.u64",std::ios::binary),freeIndex(out+"/free_leaf_indices.u64",std::ios::binary),groundIndex(out+"/native_ground_occupied_leaf_indices.u64",std::ios::binary),obstacleIndex(out+"/other_occupied_leaf_indices.u64",std::ios::binary);size_t occupiedCount=0,freeCount=0,groundCount=0,obstacleCount=0,total=0;uint16_t endian=1;need(*(unsigned char*)&endian==1&&sizeof(float)==4&&sizeof(int32_t)==4,"binary little-endian32bit layout");
 for(auto it=map.octree()->begin_leafs();it!=map.octree()->end_leafs();++it){pcl::PointXYZ q(it.getX(),it.getY(),it.getZ());/* dataset world is already Z-up: no world-axis rotation */bool occ=map.octree()->isNodeOccupied(*it);float vals[5]={q.x,q.y,q.z,float(it.getSize()),float(it->getOccupancy())};int32_t ints[3]={it->getOccupancyType(),it->getNodeRefId(),occ?1:0};leaves.write((char*)vals,sizeof(vals));leaves.write((char*)ints,sizeof(ints));uint64_t index=total++;if(occ){occupiedIndex.write((char*)&index,8);++occupiedCount;if(ints[0]==RtabmapColorOcTreeNode::kTypeGround){++groundCount;groundIndex.write((char*)&index,8);}else{++obstacleCount;obstacleIndex.write((char*)&index,8);}}else{++freeCount;freeIndex.write((char*)&index,8);}}
 leaves.close();std::vector<int> obs,free,ground;std::vector<double> probs;auto cloud=map.createCloud(0,&obs,&free,&ground,true,nullptr,&probs);need(cloud->size()==probs.size(),"native probability correspondence");auto endpoints=pcl::PointCloud<pcl::PointXYZRGB>::Ptr(new pcl::PointCloud<pcl::PointXYZRGB>);for(int i:obs)endpoints->push_back(cloud->at(i));for(int i:ground)endpoints->push_back(cloud->at(i));need(!endpoints->empty(),"native occupied geometry nonempty");auto phone=endpoints;need(pcl::io::savePLYFileBinary(out+"/occupied_ground_endpoints.ply",*phone)==0,"geometry export");std::ofstream result(out+"/RESULT.txt");result<<"frames="<<n<<"\nleafRecords="<<total<<"\noccupiedLeaves="<<occupiedCount<<"\nfreeLeaves="<<freeCount<<"\nnativeGroundOccupiedLeaves="<<groundCount<<"\notherOccupiedLeaves="<<obstacleCount<<"\nendpointCloudPoints="<<phone->size()<<"\nnativeCloudObstaclePoints="<<obs.size()<<"\nnativeCloudGroundPoints="<<ground.size()<<"\nnativeCloudFreePoints="<<free.size()<<"\nunknownPolicy=unrepresented_not_free\nverifiedFloorSupport=false\n";std::cout<<"COMPLETE "<<n<<" leafRecords="<<total<<" endpointPoints="<<phone->size()<<std::endl;return 0;
}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<std::endl;return 2;}}
